void PrivateAiInternalsPageHandlerAsyncWaiter::Connect(
    const std::string& url, const std::string& api_key, const std::string& proxy_url, bool use_token_attestation) {
  base::RunLoop loop;
  proxy_->Connect(
      std::move(url),
      std::move(api_key),
      std::move(proxy_url),
      std::move(use_token_attestation),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}



void PrivateAiInternalsPageHandlerAsyncWaiter::Close(
    ) {
  base::RunLoop loop;
  proxy_->Close(
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}



void PrivateAiInternalsPageHandlerAsyncWaiter::SendRequest(
    const std::string& feature_name, const std::string& request, PrivateAiResponsePtr* out_response) {
  base::RunLoop loop;
  proxy_->SendRequest(
      std::move(feature_name),
      std::move(request),
      base::BindOnce(
          [](base::RunLoop* loop,
             PrivateAiResponsePtr* out_response
,
             PrivateAiResponsePtr response) {*out_response = std::move(response);
            loop->Quit();
          },
          &loop,
          out_response));
  loop.Run();
}

PrivateAiResponsePtr PrivateAiInternalsPageHandlerAsyncWaiter::SendRequest(
    const std::string& feature_name, const std::string& request) {
  PrivateAiResponsePtr async_wait_result;
  SendRequest(std::move(feature_name),std::move(request),&async_wait_result);
  return async_wait_result;
}






